using Godot;
using Settings=Godot.Collections.Dictionary;

public partial class EnvironmentActorDefinitionOperations : RefCounted
{
    private static Resource Property(string id,string title,Variant value,Settings hints,bool animate=false)
    {var property=ActorProperty.create(new StringName(id),title,value,animate);property.Get("options").AsGodotDictionary().Merge(hints,true);return property;}
    public Resource create(Resource basis)
    {
        var definition=basis.Duplicate(true);definition.Set("type_id",new StringName("environment_asset"));definition.Set("display_name","Environment Asset");definition.Set("category","Environment");definition.Set("description","Linked terrain, placed models and instanced scatter from Environment Creator.");definition.Set("icon",GD.Load<Texture2D>("res://resources/Images/ActorIcons/EnvironmentAsset.svg"));definition.Set("runtime_scene",GD.Load<PackedScene>("res://Workspaces/EnvironmentWorkspace/environment_actor.tscn"));var properties=definition.Get("properties").AsGodotArray();properties.Add(Property("environment_path","Environment document", "",new Settings {["file_picker"]=true,["extensions"]=new Godot.Collections.Array {"tres","res"},["native_resource_types"]=new Godot.Collections.Array {"KiwiEnvironmentDocument"},["file_resource_mode"]="uneditable",["group"]="Environment"}));properties.Add(Property("environment_open","Edit environment",false,new Settings {["environment_open"]=true,["group"]="Environment",["no_keyframes"]=true}));properties.Add(Property("physics","Environment collision",new Settings {["enabled"]=true,["body_mode"]=1,["shape"]=6,["gravity"]=0.0},new Settings {["inspector_hidden"]=true,["group"]="Physics"}));foreach(var entry in new[]{("include_lighting","Include authored lights",true),("include_atmosphere","Use authored world / sky",false)})properties.Add(Property(entry.Item1,entry.Item2,entry.Item3,new Settings {["group"]="Environment"}));properties.Add(Property("climate_time","Time of day override (-1 = inherit)",-1.0,new Settings {["group"]="Climate override",["min"]=-1.0,["max"]=24.0,["step"]=.05,["suffix"]=" h"},true));properties.Add(Property("climate_weather","Weather override",0,new Settings {["group"]="Climate override",["min"]=0,["max"]=7,["step"]=1,["choices"]=new Godot.Collections.Array {"Inherit","Clear","Cloudy","Rain","Storm","Snow","Fog","Dust"}},true));foreach(var entry in new[]{("climate_intensity","Weather intensity override"),("climate_clouds","Cloud coverage override")})properties.Add(Property(entry.Item1,entry.Item2,-1.0,new Settings {["group"]="Climate override",["min"]=-1.0,["max"]=1.0,["step"]=.01},true));properties.Add(Property("climate_temperature_offset","Temperature offset (°C)",0.0,new Settings {["group"]="Climate override",["min"]=-100.0,["max"]=100.0,["step"]=.1},true));properties.Add(Property("climate_wind_add","Wind velocity addition (m/s)",Vector3.Zero,new Settings {["group"]="Climate override",["min"]=-250.0,["max"]=250.0,["step"]=.1},true));return definition;
    }
}
